// Parse string JSON safely from LLM output
const rawOutput = $input.first().json.output;

// Remove markdown backticks if present
const cleanJsonString = rawOutput
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse into an actual object
const parsedData = JSON.parse(cleanJsonString);

// Return clean fields to downstream nodes
return [{
  json: {
    telegram_alert: parsedData.telegram_alert,
    email_draft: parsedData.email_draft
  }
}];

